function countOnes(n: number): number {
  if (n <= 0) return 0;
  if (n < 10) return 1;
  let p = 1;
  while (p * 10 <= n) p *= 10;
  const d = Math.floor(n / p), rest = n % p;
  const lead = d === 1 ? rest + 1 : p;
  return lead + d * countOnes(p - 1) + countOnes(rest);
}

