function countOnes(n: number): number {
  let total = 0;
  for (let p = 1; p <= n; p *= 10) {
    const high = Math.floor(n / (p * 10));
    const cur = Math.floor(n / p) % 10;
    const low = n % p;
    total += high * p;
    if (cur > 1) total += p;
    else if (cur === 1) total += low + 1;
  }
  return total;
}

